"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface AvatarProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Naam waaruit de initialen worden afgeleid. */
  name?: string;
  /** Eigen letters in plaats van de afgeleide initialen, bv. een trigram. */
  initials?: string;
  src?: string;
  alt?: string;
  size?: number;
  /** Vierkant met afgeronde hoeken in plaats van rond. */
  square?: boolean;
  /** Overschrijft de achtergrondkleur (standaard de accentkleur). */
  color?: string;
  /** Statusstip rechtsonder. */
  status?: "online" | "busy" | "offline";
}

export function initialsFrom(name: string): string {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}

/** Avatar — foto of initialen, met optionele statusstip. */
export const Avatar = React.forwardRef<HTMLSpanElement, AvatarProps>(function Avatar(
  { name = "", initials, src, alt, size = 36, square, color, status, className, style, children, ...rest },
  ref
) {
  const [failed, setFailed] = React.useState(false);
  const showImage = src && !failed;

  return (
    <span
      ref={ref}
      className={cn("lui-avatar", square && "lui-avatar-square", className)}
      style={{
        width: size,
        height: size,
        fontSize: Math.round(size * 0.38),
        background: color,
        ...style,
      }}
      {...rest}
    >
      {showImage ? (
        <img className="lui-avatar-img" src={src} alt={alt ?? name} onError={() => setFailed(true)} />
      ) : (
        (children ?? initials ?? initialsFrom(name))
      )}
      {status && (
        <span
          className={cn("lui-avatar-status", `lui-avatar-status-${status}`)}
          style={{ width: Math.max(8, size * 0.26), height: Math.max(8, size * 0.26) }}
        />
      )}
    </span>
  );
});

export interface AvatarGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Maximaal aantal zichtbare avatars; de rest wordt "+n". */
  max?: number;
  size?: number;
}

/** AvatarGroup — overlappende rij avatars met een "+n"-teller. */
export const AvatarGroup = React.forwardRef<HTMLDivElement, AvatarGroupProps>(function AvatarGroup(
  { max = 4, size = 30, className, children, ...rest },
  ref
) {
  const items = React.Children.toArray(children);
  const shown = items.slice(0, max);
  const rest_ = items.length - shown.length;

  return (
    <div ref={ref} className={cn("lui-avatar-group", className)} {...rest}>
      {shown.map((child, index) =>
        React.isValidElement(child)
          ? React.cloneElement(child as React.ReactElement<AvatarProps>, { size, key: index })
          : child
      )}
      {rest_ > 0 && (
        <span className="lui-avatar lui-avatar-more" style={{ width: size, height: size, fontSize: size * 0.34 }}>
          +{rest_}
        </span>
      )}
    </div>
  );
});

/* ============================ Avatar ============================ */
.lui-avatar {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: var(--r-full); background: var(--accent); color: var(--accent-fg);
  font-weight: 650; letter-spacing: -0.01em; flex: none; overflow: visible;
  user-select: none;
}
.lui-avatar-square { border-radius: var(--r-sm); }
.lui-avatar-img {
  width: 100%; height: 100%; object-fit: cover;
  border-radius: inherit; display: block;
}
.lui-avatar-status {
  position: absolute; right: 0; bottom: 0;
  border-radius: var(--r-full); border: 2px solid var(--surface);
}
.lui-avatar-status-online { background: var(--green); }
.lui-avatar-status-busy { background: var(--amber); }
.lui-avatar-status-offline { background: var(--text-3); }

.lui-avatar-group { display: inline-flex; align-items: center; }
.lui-avatar-group > .lui-avatar { margin-left: -8px; box-shadow: 0 0 0 2px var(--surface); }
.lui-avatar-group > .lui-avatar:first-child { margin-left: 0; }
.lui-avatar-more { background: var(--surface-3); color: var(--text-2); }

/* ---------- Motion: groep waaiert open bij hover ---------- */
.lui-avatar-group > .lui-avatar { transition: margin var(--dur-slow) var(--ease-pop), transform var(--dur) var(--ease-pop); }
.lui-avatar-group:hover > .lui-avatar:not(:first-child) { margin-left: -2px; }
.lui-avatar-group > .lui-avatar:hover { transform: translateY(-3px); z-index: 1; }
.lui-avatar-img { animation: lui-overlay-in .3s var(--ease) both; }
